// REZONANCE VN ENGINE - runtime script data model.
// Flat node model on purpose: JsonUtility cannot serialize polymorphic lists, and the Act has
// tens of thousands of nodes. One class carries the payload for every VNNodeKind; unused fields stay null.
// Generated by the importer from the READABLE markdown - never hand-edit Data/*.json.
using System;
using System.Collections.Generic;

namespace Rezonance.VN.Core
{
    /// <summary>Serialization version of the generated script data. Bump on breaking shape changes.</summary>
    public static class VNDataFormat
    {
        public const int Version = 1;
    }

    /// <summary>One selectable line inside a choice menu.</summary>
    [Serializable]
    public sealed class VNMenuOption
    {
        public string id;
        /// <summary>Option text as written in the source (RU seed for localization).</summary>
        public string label;
        /// <summary>Branch the option leads to. Null when the importer could not resolve it.</summary>
        public string targetBranchId;
        public bool resolved;
        /// <summary>True when the option was matched by exact heading, false when fuzzy - see validation report.</summary>
        public string matchMode;
    }

    /// <summary>Single script node. Localization key equals <see cref="id"/>.</summary>
    [Serializable]
    public sealed class VNNode
    {
        public string id;
        public VNNodeKind kind;
        /// <summary>Speaker label exactly as in the source, e.g. "IRENA" (upper case) or "Vy".</summary>
        public string speaker;
        public VNSpeakerRole role;
        /// <summary>Source (RU) text of the line/remark/narration.</summary>
        public string text;
        /// <summary>Delivery brief in parentheses: "shtopotom", "neglyako".</summary>
        public string delivery;
        /// <summary>Menu prompt ("Chto delayete Vy:") when kind == Menu.</summary>
        public string menuPrompt;
        public List<VNMenuOption> options;
        /// <summary>Branch to resume after a forked branch finishes (importer computes: the branch after the option group).</summary>
        public string resumeBranchId;
        /// <summary>Raw conditional text for kind == Conditional.</summary>
        public string conditionRaw;
        /// <summary>Evaluable expression for kind == Conditional; empty means "not bound yet" - runtime treats it as false and the validation report lists it.</summary>
        public string conditionExpr;
        public string targetBranchId;
        /// <summary>Backdrop key when the source itself names a location (best effort, overlay wins).</summary>
        public string backdropHint;
        /// <summary>1-based line number in the markdown, for traceability and click-to-source.</summary>
        public int sourceLine;

        public VNNodeId Parsed => new VNNodeId(id);
        public bool HasOptions => options != null && options.Count > 0;
    }

    /// <summary>Branch = one "###" block. Menu targets and their continuations are branches too.</summary>
    [Serializable]
    public sealed class VNBranchDef
    {
        public string id;
        public string sceneId;
        public string title;
        public int sourceLine;
        public List<VNNode> nodes;

        public int Count => nodes == null ? 0 : nodes.Count;
    }

    /// <summary>Scene = one "##" block, holding its branches in document order.</summary>
    [Serializable]
    public sealed class VNSceneDef
    {
        public string id;
        public string title;
        public int sourceLine;
        public List<VNBranchDef> branches;

        public int BranchCount => branches == null ? 0 : branches.Count;
    }

    /// <summary>Glossary entry from the document tail; shown in the in-game dictionary.</summary>
    [Serializable]
    public sealed class VNGlossaryEntry
    {
        public string id;
        public string term;
        public string definition;
    }

    /// <summary>Root of the generated script for one act.</summary>
    [Serializable]
    public sealed class VNScriptData
    {
        public int formatVersion = VNDataFormat.Version;
        public string actId;
        /// <summary>Absolute or project-relative path of the source markdown.</summary>
        public string sourcePath;
        /// <summary>SHA-256 (hex, lowercase) of the source at import time.</summary>
        public string sourceSha;
        public System.DateTime importedAtUtc;
        public List<VNSceneDef> scenes;
        public List<VNGlossaryEntry> glossary;
    }

    /// <summary>Read-only index over <see cref="VNScriptData"/>. Built once on load; O(1) lookups everywhere.</summary>
    public sealed class VNDataRegistry
    {
        private readonly Dictionary<string, VNNode> nodesById = new Dictionary<string, VNNode>();
        private readonly Dictionary<string, VNBranchDef> branchesById = new Dictionary<string, VNBranchDef>();
        private readonly Dictionary<string, VNSceneDef> scenesById = new Dictionary<string, VNSceneDef>();
        private readonly Dictionary<string, int> branchOrder = new Dictionary<string, int>();
        private readonly List<VNSceneDef> sceneList = new List<VNSceneDef>();
        private readonly HashSet<string> speakerLabels = new HashSet<string>(StringComparer.Ordinal);

        public VNScriptData Data { get; private set; }
        public IReadOnlyList<VNSceneDef> Scenes => sceneList;
        public IReadOnlyCollection<string> SpeakerLabels => speakerLabels;
        public int NodeCount => nodesById.Count;
        public int BranchCount => branchesById.Count;

        public static VNDataRegistry Build(VNScriptData data)
        {
            var reg = new VNDataRegistry { Data = data };
            if (data == null || data.scenes == null) return reg;

            foreach (var scene in data.scenes)
            {
                if (scene == null || string.IsNullOrEmpty(scene.id)) continue;
                reg.sceneList.Add(scene);
                reg.scenesById[scene.id] = scene;
                if (scene.branches == null) continue;

                for (var b = 0; b < scene.branches.Count; b++)
                {
                    var branch = scene.branches[b];
                    if (branch == null || string.IsNullOrEmpty(branch.id)) continue;
                    reg.branchesById[branch.id] = branch;
                    reg.branchOrder[branch.id] = b;
                    if (branch.nodes == null) continue;

                    foreach (var node in branch.nodes)
                    {
                        if (node == null || string.IsNullOrEmpty(node.id)) continue;
                        reg.nodesById[node.id] = node;
                        if (!string.IsNullOrEmpty(node.speaker)) reg.speakerLabels.Add(node.speaker);
                    }
                }
            }
            return reg;
        }

        public bool TryGetNode(string id, out VNNode node) => nodesById.TryGetValue(id ?? string.Empty, out node);
        public VNNode GetNode(string id) => nodesById.TryGetValue(id ?? string.Empty, out var n) ? n : null;
        public bool TryGetBranch(string id, out VNBranchDef branch) => branchesById.TryGetValue(id ?? string.Empty, out branch);
        public VNBranchDef GetBranch(string id) => branchesById.TryGetValue(id ?? string.Empty, out var b) ? b : null;
        public bool TryGetScene(string id, out VNSceneDef scene) => scenesById.TryGetValue(id ?? string.Empty, out scene);
        public VNSceneDef GetScene(string id) => scenesById.TryGetValue(id ?? string.Empty, out var s) ? s : null;

        /// <summary>Index of the branch inside its scene, document order.</summary>
        public int BranchIndex(string branchId) => branchOrder.TryGetValue(branchId ?? string.Empty, out var i) ? i : -1;

        /// <summary>Next branch in the same scene, or null when the scene ends.</summary>
        public VNBranchDef NextBranch(VNBranchDef branch)
        {
            if (branch == null || !TryGetScene(branch.sceneId, out var scene) || scene.branches == null) return null;
            var idx = BranchIndex(branch.id);
            if (idx < 0 || idx + 1 >= scene.branches.Count) return null;
            return scene.branches[idx + 1];
        }

        /// <summary>First branch of the next scene in document order, or null at the end of the act.</summary>
        public VNBranchDef FirstBranchOfNextScene(VNSceneDef scene)
        {
            if (scene == null) return null;
            var idx = sceneList.IndexOf(scene);
            if (idx < 0 || idx + 1 >= sceneList.Count) return null;
            var next = sceneList[idx + 1];
            return next.branches != null && next.branches.Count > 0 ? next.branches[0] : null;
        }

        /// <summary>Resolves a branch by its heading inside a scene - used to bind menu options.</summary>
        public VNBranchDef FindBranchByTitle(VNSceneDef scene, string title)
        {
            if (scene == null || scene.branches == null || string.IsNullOrEmpty(title)) return null;
            for (var i = 0; i < scene.branches.Count; i++)
            {
                if (string.Equals(scene.branches[i].title, title, StringComparison.Ordinal)) return scene.branches[i];
            }
            for (var i = 0; i < scene.branches.Count; i++)
            {
                if (string.Equals(VNSlug.Of(scene.branches[i].title), VNSlug.Of(title), StringComparison.Ordinal)) return scene.branches[i];
            }
            return null;
        }

        /// <summary>Counters used by the validation report (see ARCHITECTURE.md section 1).</summary>
        public void GetCounts(out int scenes, out int branches, out int nodes, out int menus, out int conditionals, out int miniGames, out int screenTexts)
        {
            scenes = sceneList.Count;
            branches = branchesById.Count;
            nodes = nodesById.Count;
            menus = conditionals = miniGames = screenTexts = 0;
            foreach (var node in nodesById.Values)
            {
                switch (node.kind)
                {
                    case VNNodeKind.Menu: menus++; break;
                    case VNNodeKind.Conditional: conditionals++; break;
                    case VNNodeKind.MiniGame: miniGames++; break;
                    case VNNodeKind.ScreenText: screenTexts++; break;
                }
            }
        }
    }
}
